
'use client';

import React, { useEffect, useState, useRef } from 'react';
import type { Options, SourceInfo } from 'plyr';
import { useIsMobile } from '@/hooks/use-mobile';
import Plyr from 'plyr-react';

interface VideoPlayerProps {
  source: SourceInfo;
  poster?: string;
  previewThumbnailsSrc?: string;
  autoplay?: boolean;
  loop?: boolean;
  muted?: boolean;
  controls?: boolean;
  onReady?: () => void;
}

const VideoPlayer = ({
  source,
  poster,
  previewThumbnailsSrc,
  autoplay,
  loop,
  muted,
  controls = true,
  onReady,
}: VideoPlayerProps) => {
  const ref = useRef(null);
  const [isClient, setIsClient] = useState(false);
  const isMobile = useIsMobile();

  useEffect(() => {
    setIsClient(true);
  }, []);

  // Effect to attach the 'ready' event listener
  useEffect(() => {
    const plyrInstance = (ref.current as any)?.plyr;
    if (plyrInstance && onReady) {
      const handleReady = () => {
        onReady();
      };
      
      plyrInstance.on('ready', handleReady);

      // Cleanup function to remove the event listener
      return () => {
        if (plyrInstance) {
          plyrInstance.off('ready', handleReady);
        }
      };
    }
  }, [ref, onReady, isClient]); // Depend on isClient to ensure it runs client-side


  if (!isClient) {
    return <div className="plyr-react plyr" />; // Render an empty div on the server
  }

  const useThumbnails = !isMobile && !!previewThumbnailsSrc;

  const options: Options = {
    settings: ['quality', 'speed', 'loop'],
    quality: {
      default: isMobile ? 576 : 1080,
      options: [4320, 2160, 1440, 1080, 720, 576, 480, 360, 240],
    },
    previewThumbnails: {
      enabled: useThumbnails,
      src: useThumbnails ? previewThumbnailsSrc! : '',
    },
    fullscreen: {
      enabled: true,
      fallback: true,
      iosNative: true,
    },
    autoplay: autoplay || false,
    loop: { active: loop || false },
    muted: muted || false,
    controls: controls
      ? [
          'play-large',
          'play',
          'progress',
          'current-time',
          'mute',
          'volume',
          'captions',
          'settings',
          'pip',
          'airplay',
          'fullscreen',
        ]
      : [],
  };

  const fullSource = { ...source, poster };

  return <Plyr ref={ref} source={fullSource} options={options} />;
};

export default VideoPlayer;
